"""Generate the installed top-level interface reference from ``fp_ops.__all__``."""

from __future__ import annotations

import inspect
import sys
from pathlib import Path
from typing import Any

import fp_ops

ROOT = Path(__file__).resolve().parents[1]
OUTPUT = ROOT / "docs" / "api-reference.md"


def signature(value: Any) -> str | None:
    try:
        return str(inspect.signature(value))
    except (TypeError, ValueError):
        return None


def render() -> str:
    lines = [
        "# FP-Ops interface reference",
        "",
        "<!-- Generated by scripts/generate_api_reference.py. -->",
        "",
        "All names below are installed top-level exports from `fp_ops`.",
        "",
    ]
    for name in sorted(fp_ops.__all__):
        value = getattr(fp_ops, name)
        lines.extend([f"## `{name}`", ""])
        if name == "__version__":
            lines.extend([f"`{value}`", ""])
            continue
        if name == "Operation":
            lines.extend(
                [
                    "Construct with `operation`, `result_operation`, an "
                    "environment constructor, or another FP-Ops combinator.",
                    "",
                ]
            )
            for method_name in ("run", "then", "map", "flat_map"):
                method = getattr(value, method_name)
                lines.extend(
                    [
                        "```python",
                        f"{method_name}{inspect.signature(method)}",
                        "```",
                        "",
                    ]
                )
            continue
        value_signature = signature(value)
        if value_signature is not None:
            lines.extend(
                [
                    "```python",
                    f"{name}{value_signature}",
                    "```",
                    "",
                ]
            )
        else:
            lines.extend([f"`from fp_ops import {name}`", ""])
        description = inspect.getdoc(value)
        if description:
            lines.extend([description.splitlines()[0], ""])
    return "\n".join(lines)


if __name__ == "__main__":
    rendered = render()
    if "--check" in sys.argv:
        if not OUTPUT.exists() or OUTPUT.read_text(encoding="utf-8") != rendered:
            raise SystemExit(
                "docs/api-reference.md is stale; regenerate it with "
                "scripts/generate_api_reference.py"
            )
    else:
        OUTPUT.write_text(rendered, encoding="utf-8")
